package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.chronicle.*; import com.wizzadrds.theworldremembers.voice.VoicePacket; import com.mojang.blaze3d.platform.InputConstants; import net.fabricmc.api.ClientModInitializer; import net.fabricmc.fabric.api.client.keymapping.v1.KeyMappingHelper; import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents; import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking; import net.minecraft.client.KeyMapping; import net.minecraft.client.Minecraft; import org.lwjgl.glfw.GLFW;
public final class TheWorldRemembersClient implements ClientModInitializer{private static volatile VoicePacket lastVoice;private static KeyMapping openChronicles;public static VoicePacket lastVoice(){return lastVoice;}public void onInitializeClient(){ClientPlayNetworking.registerGlobalReceiver(VoicePacket.TYPE,(payload,context)->lastVoice=payload);ClientPlayNetworking.registerGlobalReceiver(ChroniclePacket.TYPE,(payload,context)->context.client().execute(()->context.client().gui.setScreen(new ChronicleScreen(payload.content()))));openChronicles=KeyMappingHelper.registerKeyMapping(new KeyMapping("key.the_world_remembers.chronicles",InputConstants.Type.KEYSYM,GLFW.GLFW_KEY_J,KeyMapping.Category.MISC));ClientTickEvents.END_CLIENT_TICK.register(client->{while(openChronicles.consumeClick())ClientPlayNetworking.send(new ChronicleRequestPacket());});}}
